/**
 * Unit tests for the JavaScript `getAbsorptionCoefficients` function.
 * 
 * This script executes test cases specified in the CSV file
 * `absorption_test_cases.csv`. The file has one test case per row,
 * comprising a temperature, pressure, relative humidity, frequency,
 * and expected absorption coefficient.
 * 
 * The test cases were generated by the `generate_absorption_test_cases.py`
 * Python script, which uses the `acoustics` Python package (available
 * from PyPI) to compute absorption coefficients.
 *
 * To run the tests with Node.js:
 *
 *    node test-get-absorption-coefficients.js
 */

import fs from 'fs';
import readline from 'readline';
import path from 'path';
import { fileURLToPath } from 'url';
import { fahrenheitToKelvin, atmToKpa, getAbsorptionCoefficients }
    from './absorption-utils.js';

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);

const csvFilePath = path.join(__dirname, 'absorption_test_cases.csv');

async function testGetAbsorptionCoefficients() {

    const fileStream = fs.createReadStream(csvFilePath);

    const rl = readline.createInterface({
        input: fileStream,
        crlfDelay: Infinity
    });

    let lineNum = 0;
    let errorCount = 0;

    for await (const line of rl) {

        // Skip header line.
        if (lineNum++ == 0)
            continue;

        const values = line.split(',');

        const t = fahrenheitToKelvin(parseFloat(values[0]));
        const p = atmToKpa(parseFloat(values[1]));
        const h = parseFloat(values[2]);
        const f = parseFloat(values[3]);
        const expectedAlpha = parseFloat(values[4]);

        // Invoke the function from get-absorption-coefficients.js
        // Returns [alphaTotals, alphaOs, alphaNs, alphaOthers]
        const results = getAbsorptionCoefficients(t, p, h, [f]);
        const alpha = results[0][0];

        const relativeError =
            Math.abs((alpha - expectedAlpha) / expectedAlpha);

        if (relativeError > 1e-6) {
            console.error(
                `Test ${lineNum - 1} failed: ${t},${p},${h},${f},` +
                `${expectedAlpha},${alpha},${relativeError}`);
            errorCount++;
        }

    }

    if (errorCount == 0) {
        console.log(`Testing complete. All ${lineNum - 1} tests passed.`);
    } else {
        console.log(
            `Testing complete. ${errorCount} of ${lineNum - 1} tests failed.`);
    }
    
}

testGetAbsorptionCoefficients().catch(err => console.error(err));
